@Composable private fun ReviewDialog(o:Offer,close:()->Unit,approve:(Offer)->Unit,reject:(Offer,String)->Unit){var type by remember(o.id){mutableStateOf(o.marginType)};var value by remember(o.id){mutableStateOf(if(o.margin==0.0)"" else o.margin.toString())};var reason by remember(o.id){mutableStateOf("")};val a=number(o.official)?:0L;val b=number(o.market)?:0L;val margin=value.toDoubleOrNull()?:0.0;fun add(base:Long):Long=if(type==MarginType.PERCENT)base+(base*margin/100.0).toLong()else base+margin.toLong();val fo=add(a);val fm=add(b);AlertDialog(onDismissRequest=close,title={Text("بررسی آگهی")},text={Column(Modifier.heightIn(max=600.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){Text(o.name,fontWeight=FontWeight.Bold);if(o.photo.isNotBlank())PhotoView(o.photo);Text("قیمت تامین‌کننده رسمی: ${o.official}");Text("قیمت تامین‌کننده غیررسمی: ${o.market}");Text("مکان تحویل: ${o.place}");Text("زمان تحویل: ${o.time}");Text("سود مدیریت روی هر دو قیمت اعمال می‌شود:");Row{FilterChip(selected=type==MarginType.PERCENT,onClick={type=MarginType.PERCENT},label={Text("درصد")});Spacer(Modifier.width(8.dp));FilterChip(selected=type==MarginType.TOMAN,onClick={type=MarginType.TOMAN},label={Text("تومان")})};OutlinedTextField(value,{value=it.filter{c->c.isDigit()||c=='.'}},Modifier.fillMaxWidth(),singleLine=true,label={Text("مقدار سود")});Text("قیمت نهایی رسمی: ${money(fo)}",fontWeight=FontWeight.Bold,color=Gold);Text("قیمت نهایی غیررسمی: ${money(fm)}",fontWeight=FontWeight.Bold,color=Gold);OutlinedTextField(reason,{reason=it},Modifier.fillMaxWidth(),label={Text("دلیل اصلاحیه")})}},confirmButton={Button({approve(o.copy(status=Status.APPROVED,marginType=type,margin=margin,publishedOfficial=money(fo),publishedMarket=money(fm)))}){Text("تأیید و انتشار")}},dismissButton={Row{TextButton(close){Text("بازگشت")};TextButton({reject(o,reason.ifBlank{"لطفاً اطلاعات آگهی اصلاح شود"})}){Text("ثبت اصلاحیه")}}})}

@Composable private fun OfferFormDialog(old:Offer?,owner:String,admin:Boolean,close:()->Unit,submit:(Offer)->Unit){var name by remember{mutableStateOf(old?.name?:"")};var official by remember{mutableStateOf(old?.official?:"")};var market by remember{mutableStateOf(old?.market?:"")};var place by remember{mutableStateOf(old?.place?:"")};var time by remember{mutableStateOf(old?.time?:"")};var supplier by remember{mutableStateOf(old?.supplier?:"")};var phone by remember{mutableStateOf(old?.phone?:owner)};var description by remember{mutableStateOf(old?.description?:"")};var photo by remember{mutableStateOf(old?.photo?:"")};val context=LocalContext.current;val picker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri:Uri?->uri?.let{runCatching{context.contentResolver.takePersistableUriPermission(it,Intent.FLAG_GRANT_READ_URI_PERMISSION)};photo=it.toString()}};AlertDialog(onDismissRequest=close,title={Text(if(old==null)"ثبت آگهی" else "ویرایش آگهی")},text={Column(Modifier.heightIn(max=650.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Input("نام ماده",name){name=it};Input("قیمت تامین‌کننده رسمی",official){official=it};Input("قیمت تامین‌کننده غیررسمی",market){market=it};Input("مکان تحویل",place){place=it};Input("زمان تحویل",time){time=it};Input("نام فروشنده (فقط مدیریت)",supplier){supplier=it};Input("شماره تماس",phone){phone=digits(it).filter(Char::isDigit).take(11)};Input("توضیحات",description){description=it};Button({picker.launch(arrayOf("image/*"))},Modifier.fillMaxWidth()){Text(if(photo.isBlank())"آپلود عکس محصول" else "تغییر عکس")};if(photo.isNotBlank())PhotoView(photo)}},confirmButton={Button({if(name.isNotBlank())submit(Offer(old?.id?:0,name,official,market,place,time,supplier,phone,owner,description,photo,old?.status?:if(admin)Status.APPROVED else Status.PENDING,old?.reason?:"",old?.marginType?:MarginType.PERCENT,old?.margin?:0.0,old?.publishedOfficial?:"",old?.publishedMarket?:""))}){Text("ذخیره")}},dismissButton={TextButton(close){